// Generated by LCD Wizard - written fresh by every export.
//
// LVGL's failed checks come here (lv_conf.h, LV_ASSERT_HANDLER) in place of
// LVGL's own while(1): a line on serial saying where and what LVGL said, then
// a restart. Firmware never fails quietly. lv_conf.h names these functions, so
// keep this file beside the sketch whenever you use that lv_conf.h.
#include <Arduino.h>
#include <esp_system.h>
#include <string.h>
#include <lvgl.h>

// LVGL's last two error lines, kept quietly: said only if a check fails.
static char lw_said[2][192];

static void lw_keep(const char * buf)
{
    memcpy(lw_said[0], lw_said[1], sizeof lw_said[0]);
    size_t n = 0;
    while (buf[n] && buf[n] != '\n' && n < sizeof lw_said[1] - 1) { lw_said[1][n] = buf[n]; n++; }
    lw_said[1][n] = '\0';
}

static void lw_lvgl_log(lv_log_level_t level, const char * buf) { (void)level; lw_keep(buf); }

// Called by the sketch after lv_init(). A sketch that does not call it still
// restarts with the file and line; only LVGL's own words are missing.
extern "C" void lw_lvgl_log_start(void) { lv_log_register_print_cb(lw_lvgl_log); }

extern "C" void lw_lvgl_fail(const char * file, int line)
{
    Serial.printf("LVGL stopped the board at %s:%d - restarting.\n", file, line);
    if (lw_said[1][0]) {
        if (lw_said[0][0]) Serial.printf("LVGL's error before that: %s\n", lw_said[0]);
        Serial.printf("LVGL said: %s\n", lw_said[1]);
        // LVGL's own words for its two commonest checks (lv_assert.h), in plain ones.
        if (strstr(lw_said[1], "NULL pointer") || strstr(lw_said[1], "object is NULL"))
            Serial.println("That is: it was handed a widget or other object that does not exist (NULL) - not made yet, or a pointer never set. Not a memory fault.");
        else if (strstr(lw_said[1], "Out of memory"))
            Serial.println("That is: LVGL ran out of memory.");
    } else {
        Serial.println("What it checked is written on that line of the lvgl library.");
    }
    Serial.flush();
    delay(100);
    esp_restart();
}
